import React from 'react';
import clsx from 'clsx';
import {useThemeConfig, usePrismTheme} from '@docusaurus/theme-common';
import {
  parseCodeBlockTitle,
  parseLanguage,
  containsLineNumbers,
  useCodeWordWrap,
  PrismHighlightConfig,
  MagicCommentDirective,
  parseNumericRange,
} from '@docusaurus/theme-common/internal';
import Highlight, {defaultProps, type Language} from 'prism-react-renderer';
import Line, {CodeBlockInput} from '../Line';
import CopyButton from '@theme/CodeBlock/CopyButton';
import WordWrapButton from '@theme/CodeBlock/WordWrapButton';
import Container from '@theme/CodeBlock/Container';
import type {Props} from '@theme/CodeBlock/Content/String';

import styles from './styles.module.css';

const metastringLinesRangeRegex = /\{(?<range>[\d,-]+)\}/;

// Supported types of highlight comments
const commentPatterns = {
  js: {start: '\\/\\/', end: ''},
  jsBlock: {start: '\\/\\*', end: '\\*\\/'},
  jsx: {start: '\\{\\s*\\/\\*', end: '\\*\\/\\s*\\}'},
  bash: {start: '#', end: ''},
  html: {start: '<!--', end: '-->'},
  lua: {start: '--', end: ''},
  wasm: {start: '\\;\\;', end: ''},
  tex: {start: '%', end: ''},
};

type CommentType = keyof typeof commentPatterns;

function getCommentPattern(
  languages: CommentType[],
  magicCommentDirectives: MagicCommentDirective[],
) {
  // To be more reliable, the opening and closing comment must match
  const commentPattern = languages
    .map((lang) => {
      const {start, end} = commentPatterns[lang];
      return `(?:${start}\\s*(${magicCommentDirectives
        .flatMap((d) => [d.line, d.block?.start, d.block?.end].filter(Boolean))
        .join('|')})\\s*${end})`;
    })
    .join('|');
  // White space is allowed, but otherwise it should be on it's own line
  return new RegExp(`^\\s*(?:${commentPattern})\\s*$`);
}

/**
 * Select comment styles based on language
 */
function getAllMagicCommentDirectiveStyles(
  lang: string,
  magicCommentDirectives: MagicCommentDirective[],
) {
  switch (lang) {
    case 'js':
    case 'javascript':
    case 'ts':
    case 'typescript':
      return getCommentPattern(['js', 'jsBlock'], magicCommentDirectives);

    case 'jsx':
    case 'tsx':
      return getCommentPattern(
        ['js', 'jsBlock', 'jsx'],
        magicCommentDirectives,
      );

    case 'html':
      return getCommentPattern(
        ['js', 'jsBlock', 'html'],
        magicCommentDirectives,
      );

    case 'python':
    case 'py':
    case 'bash':
      return getCommentPattern(['bash'], magicCommentDirectives);

    case 'markdown':
    case 'md':
      // Text uses HTML, front matter uses bash
      return getCommentPattern(['html', 'jsx', 'bash'], magicCommentDirectives);

    case 'tex':
    case 'latex':
    case 'matlab':
      return getCommentPattern(['tex'], magicCommentDirectives);

    case 'lua':
    case 'haskell':
    case 'sql':
      return getCommentPattern(['lua'], magicCommentDirectives);

    case 'wasm':
      return getCommentPattern(['wasm'], magicCommentDirectives);

    default:
      // All comment types except lua, wasm and matlab
      return getCommentPattern(
        Object.keys(commentPatterns).filter(
          (pattern) =>
            !['lua', 'wasm', 'tex', 'latex', 'matlab'].includes(pattern),
        ) as CommentType[],
        magicCommentDirectives,
      );
  }
}

export class CodeBlockContentModel {
  language: string | undefined;
  rawCode: string;

  constructor(language: string | undefined, rawCode: string) {
    this.language = language;
    this.rawCode = rawCode;
  }

  parseHighlightedCode(input: CodeBlockInput): {
    language: string | undefined;
    lineClassNames: {[lineIndex: number]: string[]};
    code: string;
  } {
    const language =
      this.language ??
      parseLanguage(input.blockClassName) ??
      input.prism.defaultLanguage;

    let code = this.rawCode.replace(/\n$/, '');
    const metastring = input.metastring;
    const magicComments = input.prism.magicComments;
    // Highlighted lines specified in props: don't parse the content
    if (metastring && metastringLinesRangeRegex.test(metastring)) {
      const linesRange = metastring.match(metastringLinesRangeRegex)!.groups!
        .range!;
      if (magicComments.length === 0) {
        throw new Error(
          `A highlight range has been given in code block's metastring (\`\`\` ${metastring}), but no magic comment config is available. Docusaurus applies the first magic comment entry's className for metastring ranges.`,
        );
      }
      const metastringRangeClassName = magicComments[0]!.className;
      const lines = parseNumericRange(linesRange)
        .filter((n) => n > 0)
        .map((n) => [n - 1, [metastringRangeClassName]] as [number, string[]]);
      return {language, lineClassNames: Object.fromEntries(lines), code};
    }
    if (language === undefined) {
      return {language, lineClassNames: {}, code};
    }
    const directiveRegex = getAllMagicCommentDirectiveStyles(
      language,
      magicComments,
    );
    // Go through line by line
    const lines = code.split('\n');
    const blocks = Object.fromEntries(
      magicComments.map((d) => [d.className, {start: 0, range: ''}]),
    );
    const lineToClassName: {[comment: string]: string} = Object.fromEntries(
      magicComments
        .filter((d) => d.line)
        .map(({className, line}) => [line!, className] as [string, string]),
    );
    const blockStartToClassName: {[comment: string]: string} =
      Object.fromEntries(
        magicComments
          .filter((d) => d.block)
          .map(({className, block}) => [block!.start, className]),
      );
    const blockEndToClassName: {[comment: string]: string} = Object.fromEntries(
      magicComments
        .filter((d) => d.block)
        .map(({className, block}) => [block!.end, className]),
    );
    for (let lineNumber = 0; lineNumber < lines.length; ) {
      const line = lines[lineNumber]!;
      const match = line.match(directiveRegex);
      if (!match) {
        // Lines without directives are unchanged
        lineNumber += 1;
        continue;
      }
      const directive = match
        .slice(1)
        .find((item: string | undefined) => item !== undefined)!;
      if (lineToClassName[directive]) {
        blocks[lineToClassName[directive]!]!.range += `${lineNumber},`;
      } else if (blockStartToClassName[directive]) {
        blocks[blockStartToClassName[directive]!]!.start = lineNumber;
      } else if (blockEndToClassName[directive]) {
        blocks[blockEndToClassName[directive]!]!.range += `${
          blocks[blockEndToClassName[directive]!]!.start
        }-${lineNumber - 1},`;
      }
      lines.splice(lineNumber, 1);
    }
    code = lines.join('\n');
    const lineClassNames: {[lineIndex: number]: string[]} = {};
    Object.entries(blocks).forEach(([className, {range}]) => {
      parseNumericRange(range).forEach((l) => {
        lineClassNames[l] ??= [];
        lineClassNames[l]!.push(className);
      });
    });
    return {language, lineClassNames, code};
  }
}

export default function CodeBlockString({
  children,
  className: blockClassName = '',
  metastring,
  title: titleProp,
  showLineNumbers: showLineNumbersProp,
  language: languageProp,
}: Props): JSX.Element {
  const {
    prism: {defaultLanguage, magicComments},
  } = useThemeConfig();
  const {language, lineClassNames, code} = new CodeBlockContentModel(
    languageProp,
    children,
  ).parseHighlightedCode(
    new CodeBlockInput(
      metastring,
      blockClassName,
      new PrismHighlightConfig(defaultLanguage, magicComments),
    ),
  );
  const prismTheme = usePrismTheme();
  const wordWrap = useCodeWordWrap();

  // We still parse the metastring in case we want to support more syntax in the
  // future. Note that MDX doesn't strip quotes when parsing metastring:
  // "title=\"xyz\"" => title: "\"xyz\""
  const title = parseCodeBlockTitle(metastring) || titleProp;

  const showLineNumbers =
    showLineNumbersProp ?? containsLineNumbers(metastring);

  return (
    <Container
      as="div"
      className={clsx(
        blockClassName,
        language &&
          !blockClassName.includes(`language-${language}`) &&
          `language-${language}`,
      )}>
      {title && <div className={styles.codeBlockTitle}>{title}</div>}
      <div className={styles.codeBlockContent}>
        <Highlight
          {...defaultProps}
          theme={prismTheme}
          code={code}
          language={(language ?? 'text') as Language}>
          {({className, tokens, getLineProps, getTokenProps}) => (
            <pre
              /* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */
              tabIndex={0}
              ref={wordWrap.codeBlockRef}
              className={clsx(className, styles.codeBlock, 'thin-scrollbar')}>
              <code
                className={clsx(
                  styles.codeBlockLines,
                  showLineNumbers && styles.codeBlockLinesWithNumbering,
                )}>
                {tokens.map((line, i) => (
                  <Line
                    key={i}
                    line={line}
                    getLineProps={getLineProps}
                    getTokenProps={getTokenProps}
                    classNames={lineClassNames[i]}
                    showLineNumbers={showLineNumbers}
                  />
                ))}
              </code>
            </pre>
          )}
        </Highlight>
        <div className={styles.buttonGroup}>
          {(wordWrap.isEnabled || wordWrap.isCodeScrollable) && (
            <WordWrapButton
              className={styles.codeButton}
              onClick={() => wordWrap.toggle()}
              isEnabled={wordWrap.isEnabled}
            />
          )}
          <CopyButton className={styles.codeButton} code={code} />
        </div>
      </div>
    </Container>
  );
}

