import type {CSSProperties} from 'react';
import rangeParser from 'parse-numeric-range';
import type {PrismTheme} from 'prism-react-renderer';

export type MagicCommentConfig = {
  className: string;
  line?: string;
  block?: {start: string; end: string};
};

export class MagicCommentBlock {
  start: string;
  end: string;

  constructor(start: string, end: string) {
    this.start = start;
    this.end = end;
  }
}

export class MagicCommentDirective {
  className: string;
  line: string | undefined;
  block: MagicCommentBlock | undefined;

  constructor(
    className: string,
    line?: string,
    block?: {start: string; end: string},
  ) {
    this.className = className;
    this.line = line;
    this.block = block
      ? new MagicCommentBlock(block.start, block.end)
      : undefined;
  }
}

export function parseCodeBlockTitle(metastring?: string): string {
  const codeBlockTitleRegex = /title=(?<quote>["'])(?<title>.*?)\1/;
  return metastring?.match(codeBlockTitleRegex)?.groups!.title ?? '';
}

export function containsLineNumbers(metastring?: string): boolean {
  return Boolean(metastring?.includes('showLineNumbers'));
}

/**
 * Gets the language name from the class name (set by MDX).
 * e.g. `"language-javascript"` => `"javascript"`.
 * Returns undefined if there is no language class name.
 */
export function parseLanguage(className: string): string | undefined {
  const languageClassName = className
    .split(' ')
    .find((str) => str.startsWith('language-'));
  return languageClassName?.replace(/language-/, '');
}

export function parseNumericRange(range: string): number[] {
  return rangeParser(range);
}

export function getPrismCssVariables(prismTheme: PrismTheme): CSSProperties {
  const mapping: {[name: keyof PrismTheme['plain']]: string} = {
    color: '--prism-color',
    backgroundColor: '--prism-background-color',
  };

  const properties: {[key: string]: string} = {};
  Object.entries(prismTheme.plain).forEach(([key, value]) => {
    const varName = mapping[key];
    if (varName && typeof value === 'string') {
      properties[varName] = value;
    }
  });
  return properties;
}

